(()=>{const body=document.body;const en=body.dataset.lang==='en';const q=document.getElementById('q'),book=document.getElementById('book'),kind=document.getElementById('kind'),root=document.getElementById('records'),count=document.getElementById('result-count');const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));const paras=s=>String(s||'').split(/\n\n+/).map(p=>'<p>'+esc(p)+'</p>').join('');const list=(xs,cls='')=>xs?.length?'<ol class="'+cls+'">'+xs.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol>':'';fetch(body.dataset.source).then(r=>{if(!r.ok)throw Error(r.status);return r.json()}).then(data=>{const all=data.records;function render(){const needle=q.value.trim().toLocaleLowerCase();const rows=all.filter(r=>{if(book.value&&r.bookId!==book.value)return false;if(kind.value&&r.type!==kind.value)return false;if(!needle)return true;const hay=[r.titleMai,r.titleEn,r.summaryMai,r.summaryEn,r.bookTitleMai,r.bookTitleEn,...(r.terms||[]),...(r.outlineMai||[]),...(r.outlineEn||[]),...(r.map||[])].join(' ').toLocaleLowerCase();return hay.includes(needle)});count.textContent=en?rows.length+' of '+all.length+' units shown':all.length+' मे सँ '+rows.length+' इकाइ देखाओल गेल';root.innerHTML=rows.map(r=>{const title=en?r.titleEn:r.titleMai,summary=en?r.summaryEn:r.summaryMai,outline=en?r.outlineEn:r.outlineMai;return '<article class="record" id="'+esc(r.id)+'" data-annexure="'+(r.translationAnnexure?'true':'false')+'"><div class="meta"><span>'+esc(en?r.bookTitleEn:r.bookTitleMai)+'</span><span class="badge">'+(r.translationAnnexure?(en?'translation annexure':'अनुवाद-अनुलग्नक'):(en?'research unit':'अनुसन्धान इकाइ'))+'</span></div><h2>'+esc(title)+'</h2><div class="summary">'+paras(summary)+'</div>'+(r.terms?.length?'<ul class="terms">'+r.terms.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul>':'')+(outline?.length?'<details><summary>'+(en?'Argument outline':'तर्क-रूपरेखा')+'</summary>'+list(outline,'map')+'</details>':'')+(r.map?.length?'<details><summary>'+(en?'Translation / source map':'अनुवाद / स्रोत मानचित्र')+'</summary>'+list(r.map,'map')+'</details>':'')+'</article>'}).join('')||'<p>'+(en?'No unit matches these filters.':'एहि छनौटमे कोनो इकाइ नहि भेटल।')+'</p>'}for(const el of [q,book,kind])el.addEventListener(el===q?'input':'change',render);render()}).catch(err=>{root.innerHTML='<p role="alert">'+(en?'The research data could not be loaded.':'अनुसन्धान-दत्तांश लोड नहि भऽ सकल।')+'</p>';console.error(err)})})();